// Script to read .env.test and POST environment variables to a documentation API
const fs = require('fs');
const dotenv = require('dotenv');
const axios = require('axios');

// Load environment variables from .env.test
const envConfig = dotenv.parse(fs.readFileSync('.env.test'));

// Prepare the data to send as JSON
const payload = {
  environmentVariables: envConfig,
  timestamp: new Date().toISOString(),
  source: '.env.test'
};

// POST the data to the documentation API
axios.post('http://localhost:3003/api/doc-export', payload)
  .then(response => {
    console.log('Successfully posted environment variables:', response.data);
  })
  .catch(error => {
    console.error('Failed to post environment variables:', error.message);
  });

